        (None, config::PinFreq::Off) => "no".to_string(),
        (None, _) => "not engaged: suggest-freq pins for itself".to_string(),
    };
    let params = [
        Param::new(
            "benches",
            match &suggest {
                Some(name) => name.clone(),
                None => bench_list.join(", "),
            },
            "none",
            benches_src,
        ),
