        target_seconds,
        samples_override: samples,
        inner_override: inner,
        pin_cpus: &pin_cpus,
        report_ticks,
        seam_probes: env_probe,
        band_labels,
        decimals: decimals as usize,
        settle_time_s: settle_time,
        warm_cap_s: warm_cap,
        blocks,
        block_sleep_s,
        block_warmup_s,
        record: recorder.as_ref(),
    };

