            &seconds_value(harness::DEFAULT_WARM_CAP_S),
            warm_cap_src,
        ),
        Param::new(
            "band_labels",
            band_labels.as_str().to_string(),
            DEFAULT_BAND_LABELS.as_str(),
            band_labels_src,
        ),
        Param::new(
            "decimals",
            decimals.to_string(),
            &DEFAULT_DECIMALS.to_string(),
