    if let Some(key) = raw.tags.keys().find(|k| k.is_empty() || k.contains('=')) {
        return Err(format!("tags: {key:?} is empty or holds '='"));
    }
    Ok(Config {
        benches,
        duration,
        band_labels,
        decimals: raw.decimals,
        settle_time,
