    blocks: Option<u64>,
    /// Default `--runs` count, runs per bench.
    runs: Option<u64>,
    /// Default `--run-sleep` span spec (e.g. `"1-3s"`).
    run_sleep: Option<String>,
    /// Default `--trim-runs`, the edges of the band of run means kept (e.g. `"10-50"`).
    trim_runs: Option<String>,
