        assert_eq!(run_sleep, Some(crate::runs::DEFAULT_RUN_SLEEP_S));
        assert_eq!(trim_runs, Some(crate::series::Trim::DEFAULT));
        assert_eq!(env_probe, Some(true));
        assert_eq!(inhibit, Some(true));
